import java.util.*;

sealed interface Temperature permits Celsius, Fahrenheit { }

record Celsius(double value) implements Temperature { }

record Fahrenheit(double value) implements Temperature { }

public class Main {
    static double celsius(Temperature t) {
        return switch (t) {
            case Celsius(double v) -> v;
            case Fahrenheit(double v) -> (v - 32) * 5 / 9;
        };
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String unit = sc.next();
        double v = sc.nextDouble();
        Temperature t = unit.equals("C") ? new Celsius(v) : new Fahrenheit(v);
        System.out.printf(Locale.ROOT, "%.1f%n", celsius(t));
    }
}

